Dataspatium.assets.register("presets/api/syke-geodata.api.json","text","{\n  \"format\": \"dataspatium-api/1\",\n  \"id\": \"syke-geodata\",\n  \"name\": \"Finlands miljöcentral SYKE geodata (ArcGIS)\",\n  \"publisher\": \"Finlands miljöcentral\",\n  \"description\": \"Miljögeodata från SYKE: naturskyddsområden, vattendrag, avrinningsområden med mera. Välj tjänst och lager och hämta objekten.\",\n  \"docs\": \"https://www.syke.fi/sv/miljoinformation/oppen-information\",\n  \"license\": {\n    \"name\": \"CC BY 4.0\",\n    \"url\": \"https://creativecommons.org/licenses/by/4.0/\"\n  },\n  \"level\": 1,\n  \"country\": \"FI\",\n  \"baseUrl\": \"https://paikkatieto.ymparisto.fi/arcgis/rest/services\",\n  \"auth\": {\n    \"type\": \"none\"\n  },\n  \"family\": {\n    \"type\": \"geodata\",\n    \"kind\": \"arcgis\"\n  },\n  \"endpoints\": [],\n  \"notes\": \"Lagren hämtas från tjänsten när källan öppnas (GetCapabilities respektive tjänstekatalogen). Svaren är GeoJSON i WGS 84 och öppnas som kartor.\",\n  \"i18n\": {\n    \"en\": {\n      \"name\": \"Finnish Environment Institute SYKE geodata (ArcGIS)\",\n      \"description\": \"Environmental geodata from SYKE: nature reserves, watercourses, catchments and more. Choose a service and layer and fetch the features.\",\n      \"notes\": \"The layers are read from the service when the source is opened (GetCapabilities or the service directory). Answers are GeoJSON in WGS 84 and open as maps.\"\n    },\n    \"da\": {\n      \"name\": \"Finlands miljøcentral SYKE geodata (ArcGIS)\",\n      \"description\": \"Miljøgeodata fra SYKE: naturbeskyttelsesområder, vandløb, afstrømningsområder med mere. Vælg tjeneste og lag og hent objekterne.\",\n      \"notes\": \"Lagene hentes fra tjenesten, når kilden åbnes (GetCapabilities henholdsvis tjenestekataloget). Svarene er GeoJSON i WGS 84 og åbnes som kort.\"\n    },\n    \"nb\": {\n      \"name\": \"Finlands miljøsentral SYKE geodata (ArcGIS)\",\n      \"description\": \"Miljøgeodata fra SYKE: naturvernområder, vassdrag, nedbørfelt med mer. Velg tjeneste og lag og hent objektene.\",\n      \"notes\": \"Lagene hentes fra tjenesten når kilden åpnes (GetCapabilities respektive tjenestekatalogen). Svarene er GeoJSON i WGS 84 og åpnes som kart.\"\n    },\n    \"fi\": {\n      \"name\": \"Suomen ympäristökeskus SYKE paikkatieto (ArcGIS)\",\n      \"description\": \"Ympäristöpaikkatietoa SYKEltä: luonnonsuojelualueet, vesistöt, valuma-alueet ja muuta. Valitse palvelu ja taso ja nouda kohteet.\",\n      \"notes\": \"Tasot noudetaan palvelusta, kun lähde avataan (GetCapabilities tai palveluhakemisto). Vastaukset ovat GeoJSONia WGS 84:ssä ja avautuvat karttoina.\"\n    },\n    \"is\": {\n      \"name\": \"Landupplýsingar finnsku umhverfisstofnunarinnar SYKE (ArcGIS)\",\n      \"description\": \"Umhverfislandupplýsingar frá SYKE: náttúruverndarsvæði, vatnsföll, vatnasvið og fleira. Veldu þjónustu og lag og sæktu fitjurnar.\",\n      \"notes\": \"Lögin eru sótt úr þjónustunni þegar uppsprettan er opnuð (GetCapabilities eða þjónustuskráin). Svörin eru GeoJSON í WGS 84 og opnast sem kort.\"\n    }\n  }\n}\n");
